"use strict";(self.webpackChunksrc=self.webpackChunksrc||[]).push([[950],{2794:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Introduction","href":"/wiki/","docId":"Intro","unlisted":false},{"type":"category","label":"Config","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Config Syntax","href":"/wiki/Config/Config-Spec","docId":"Config/Config-Spec","unlisted":false}]},{"type":"category","label":"Modules","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Overview","href":"/wiki/Modules/Modules","docId":"Modules/Modules","unlisted":false},{"type":"link","label":"IMatcher","href":"/wiki/Modules/IMatcher","docId":"Modules/IMatcher","unlisted":false},{"type":"link","label":"IStereoDepth","href":"/wiki/Modules/IStereoDepth","docId":"Modules/IStereoDepth","unlisted":false},{"type":"link","label":"IFrontend","href":"/wiki/Modules/IFrontend","docId":"Modules/IFrontend","unlisted":false},{"type":"link","label":"IKeypointSelector","href":"/wiki/Modules/IKeypointSelector","docId":"Modules/IKeypointSelector","unlisted":false},{"type":"link","label":"IMotionModel","href":"/wiki/Modules/IMotionModel","docId":"Modules/IMotionModel","unlisted":false},{"type":"link","label":"IObservationFilter","href":"/wiki/Modules/IObservationFilter","docId":"Modules/IObservationFilter","unlisted":false},{"type":"link","label":"ICovariance2to3","href":"/wiki/Modules/IObservationCov","docId":"Modules/IObservationCov","unlisted":false},{"type":"link","label":"IOptimizer","href":"/wiki/Modules/IOptimizer","docId":"Modules/IOptimizer","unlisted":false}]},{"type":"category","label":"Extend MAC-VO","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Dataset Customization","href":"/wiki/Redevelop/NewDataset","docId":"Redevelop/NewDataset","unlisted":false},{"type":"link","label":"Frontend Network","href":"/wiki/Redevelop/NewFrontend","docId":"Redevelop/NewFrontend","unlisted":false},{"type":"link","label":"Backend Optimizer","href":"/wiki/Redevelop/NewOptimizer","docId":"Redevelop/NewOptimizer","unlisted":false}],"href":"/wiki/category/extend-mac-vo"},{"type":"category","label":"Utility","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"AutoScalingTensor","href":"/wiki/Utility/AutoScalingTensor","docId":"Utility/AutoScalingTensor","unlisted":false},{"type":"link","label":"SubclassRegistry","href":"/wiki/Utility/SubclassRegistry","docId":"Utility/SubclassRegistry","unlisted":false}],"href":"/wiki/category/utility"},{"type":"link","label":"ROS2 Integration","href":"/wiki/ROS","docId":"ROS","unlisted":false}]},"docs":{"Config/Config-Spec":{"id":"Config/Config-Spec","title":"Config Syntax","description":"Syntax of Config Files","sidebar":"tutorialSidebar"},"Intro":{"id":"Intro","title":"Introduction","description":"This document is for people who want to extend and redevelop based on the codebase of MAC-VO. The document is organized in the following order","sidebar":"tutorialSidebar"},"Modules/IFrontend":{"id":"Modules/IFrontend","title":"IFrontend","description":"The IFrontend interface provides a unified module for joint estimation of depth and optical flow from stereo image pairs, with optional uncertainty estimation for both tasks.","sidebar":"tutorialSidebar"},"Modules/IKeypointSelector":{"id":"Modules/IKeypointSelector","title":"IKeypointSelector","description":"The IKeypointSelector interface is responsible for selecting keypoints from stereo frames for tracking and mapping. It can utilize depth, flow, and uncertainty information to make intelligent selections.","sidebar":"tutorialSidebar"},"Modules/IMatcher":{"id":"Modules/IMatcher","title":"IMatcher","description":"The IMatcher interface is responsible for estimating dense optical flow between two frames, with optional uncertainty estimation and occlusion mask prediction.","sidebar":"tutorialSidebar"},"Modules/IMotionModel":{"id":"Modules/IMotionModel","title":"IMotionModel","description":"The IMotionModel interface is responsible for providing initial pose estimates for new frames in the visual odometry pipeline. It can utilize various sources of information including flow, depth, and previous pose estimates.","sidebar":"tutorialSidebar"},"Modules/IObservationCov":{"id":"Modules/IObservationCov","title":"ICovariance2to3","description":"The ICovariance2to3 interface is responsible for converting 2D uncertainties (depth and flow) into 3D spatial covariance matrices. This is a key component for probabilistic visual odometry as described in Section III.C of the MAC-VO paper.","sidebar":"tutorialSidebar"},"Modules/IObservationFilter":{"id":"Modules/IObservationFilter","title":"IObservationFilter","description":"This module filters out the observations using some simple logic. It helps for more robust tracking and removes outliers in the system at early stage of the system.","sidebar":"tutorialSidebar"},"Modules/IOptimizer":{"id":"Modules/IOptimizer","title":"IOptimizer","description":"The IOptimizer interface is responsible for optimization tasks in the MAC-VO system. It supports both sequential and parallel execution modes, allowing optimization to run in the background when configured.","sidebar":"tutorialSidebar"},"Modules/IStereoDepth":{"id":"Modules/IStereoDepth","title":"IStereoDepth","description":"The IStereoDepth interface is responsible for estimating dense depth maps from stereo image pairs, with optional uncertainty estimation and occlusion mask prediction.","sidebar":"tutorialSidebar"},"Modules/Modules":{"id":"Modules/Modules","title":"Overview","description":"An Interface specifies a component with certain methods and properties. A Module is the actual implementation of an interface and follows the type specification provided by the interface. In MAC-VO, we strictly follow the interface-based design and write implementation-agnostic code. Therefore, all implementations of interfaces are interchangeable without any breaking changes.","sidebar":"tutorialSidebar"},"Redevelop/NewDataset":{"id":"Redevelop/NewDataset","title":"Dataset Customization","description":"Run MAC-VO stack on new datasets","sidebar":"tutorialSidebar"},"Redevelop/NewFrontend":{"id":"Redevelop/NewFrontend","title":"Frontend Network","description":"Adapt a Frontend Network to the MAC-VO codebase for downstream tasks.","sidebar":"tutorialSidebar"},"Redevelop/NewOptimizer":{"id":"Redevelop/NewOptimizer","title":"Backend Optimizer","description":"Swap the backend optimizer for different residual or graph formulation.","sidebar":"tutorialSidebar"},"ROS":{"id":"ROS","title":"ROS2 Integration","description":"MAC-VO can be integrated with ROS-2 as a single node. The implementation is tested under ROS-2 Humble.","sidebar":"tutorialSidebar"},"Utility/AutoScalingTensor":{"id":"Utility/AutoScalingTensor","title":"AutoScalingTensor","description":"For effient `torch.cat` used in data accumulation.","sidebar":"tutorialSidebar"},"Utility/SubclassRegistry":{"id":"Utility/SubclassRegistry","title":"SubclassRegistry","description":"To dynamically reflect any subclass (or descendents) from string in runtime.","sidebar":"tutorialSidebar"}}}}')}}]);